//! Committed battery for PIDASHCONV-693 (exotic charset table).
//!
//! GENERATED by /tmp/gen693_p8.py from the run-1 oracle — stratified
//! samples plus every edge cell (poison, esize2, undef bytes, error
//! texts, tail drops). Exhaustive replays live in the generator.
//!
//! Conventions: `Ok(text, spans)` = decoded text with surrogate
//! placeholders (U+FFFD) at byte offsets `spans: &[(usize, u16)]`;
//! `Parse(detail)` = UnicodeDecodeError/ValueError text; `Server` =
//! 500-class (text irrelevant); `Fallback` = form layer-1 latin-1 path.

use super::body::charset_to_supported;
use super::body_decoders as dec;

fn bytes_of(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect()
}

#[derive(Debug, PartialEq)]
enum Expect {
    Ok(&'static str, &'static [(usize, u16)]),
    Parse(&'static str),
    Server,
    Fallback,
}

fn check_stream(modname: &str, hex: &str, want: Expect) {
    let cs = charset_to_supported(modname);
    let got = match dec::decode_stream(&bytes_of(hex), &cs) {
        Ok(t) => Expect::Ok(
            Box::leak(t.text.into_boxed_str()),
            Box::leak(t.surr.into_boxed_slice()),
        ),
        Err(dec::DecodeFail::Parse(d)) => Expect::Parse(Box::leak(d.into_boxed_str())),
        Err(dec::DecodeFail::Server) => Expect::Server,
    };
    assert_eq!(got, want, "stream {modname} {hex}");
}

fn check_one(modname: &str, hex: &str, want: Expect) {
    let cs = charset_to_supported(modname);
    let got = match dec::decode_oneshot_strict(&bytes_of(hex), &cs) {
        Ok(t) => Expect::Ok(
            Box::leak(t.text.into_boxed_str()),
            Box::leak(t.surr.into_boxed_slice()),
        ),
        Err(dec::OneshotFail::Fallback) => Expect::Fallback,
        Err(dec::OneshotFail::Server) => Expect::Server,
    };
    assert_eq!(got, want, "oneshot {modname} {hex}");
}

fn check_rep(modname: &str, hex: &str, want: Expect) {
    let cs = charset_to_supported(modname);
    let got = match dec::decode_oneshot_replace(&bytes_of(hex), &cs) {
        Ok(t) => Expect::Ok(
            Box::leak(t.text.into_boxed_str()),
            Box::leak(t.surr.into_boxed_slice()),
        ),
        Err(()) => Expect::Server,
    };
    assert_eq!(got, want, "replace {modname} {hex}");
}

