#[test]
fn battery_idna_c() {
    check_one("idna", "786e2d2d6162", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d6162",
        Expect::Parse("Invalid character '\\x81'"),
    );
    check_rep("idna", "786e2d2d6162", Expect::Server);
    check_one("idna", "786e2d2d6161", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d6161",
        Expect::Parse("Invalid character '\\x80'"),
    );
    check_rep("idna", "786e2d2d6161", Expect::Server);
    check_one("idna", "786e2d2d616263", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d616263",
        Expect::Parse("Invalid character '\\x82'"),
    );
    check_rep("idna", "786e2d2d616263", Expect::Server);
    check_one("idna", "786e2d2d612d656370", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d612d656370",
        Expect::Parse("('IDNA does not round-trip', b'xn--a-ecp', b'a1.')"),
    );
    check_rep("idna", "786e2d2d612d656370", Expect::Server);
    check_one("idna", "786e2d2d30", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d30",
        Expect::Parse("incomplete punicode string"),
    );
    check_rep("idna", "786e2d2d30", Expect::Server);
    check_one("idna", "786e2d2d39", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d39",
        Expect::Parse("incomplete punicode string"),
    );
    check_rep("idna", "786e2d2d39", Expect::Server);
    check_one("idna", "786e2d2d5f", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d5f",
        Expect::Parse("Invalid extended code point '_'"),
    );
    check_rep("idna", "786e2d2d5f", Expect::Server);
    check_one("idna", "612e786e2d2d61", Expect::Server);
    check_stream(
        "idna",
        "612e786e2d2d61",
        Expect::Parse("Invalid character '\\x80'"),
    );
    check_rep("idna", "612e786e2d2d61", Expect::Server);
    check_one("idna", "2e786e2d2d61", Expect::Server);
    check_stream(
        "idna",
        "2e786e2d2d61",
        Expect::Parse("Invalid character '\\x80'"),
    );
    check_rep("idna", "2e786e2d2d61", Expect::Server);
    check_one("idna", "786e2d2d612e", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d612e",
        Expect::Parse("Invalid character '\\x80'"),
    );
    check_rep("idna", "786e2d2d612e", Expect::Server);
    check_one("idna", "584e2d2d61", Expect::Ok("XN--a", &[]));
    check_stream("idna", "584e2d2d61", Expect::Ok("XN--a", &[]));
    check_rep("idna", "584e2d2d61", Expect::Server);
    check_one(
        "idna",
        "786e2d2d6d6e6368656e2d3379612e",
        Expect::Ok("m\u{fc}nchen.", &[]),
    );
    check_stream(
        "idna",
        "786e2d2d6d6e6368656e2d3379612e",
        Expect::Ok("m\u{fc}nchen.", &[]),
    );
    check_rep("idna", "786e2d2d6d6e6368656e2d3379612e", Expect::Server);
    check_one(
        "idna",
        "786e2d2d4d4e4348454e2d335941",
        Expect::Ok("M\u{fc}NCHEN", &[]),
    );
    check_stream(
        "idna",
        "786e2d2d4d4e4348454e2d335941",
        Expect::Ok("M\u{fc}NCHEN", &[]),
    );
    check_rep("idna", "786e2d2d4d4e4348454e2d335941", Expect::Server);
    check_one("idna", "786e2d2d6e7861736d713662697869", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d6e7861736d713662697869",
        Expect::Parse("('IDNA does not round-trip', b'xn--nxasmq6bixi', b'xn--nxalkqui4ck')"),
    );
    check_rep("idna", "786e2d2d6e7861736d713662697869", Expect::Server);
    check_one(
        "idna",
        "786e2d2d78787878787878787878787878787878787878787878787878787878",
        Expect::Server,
    );
    check_stream(
        "idna",
        "786e2d2d78787878787878787878787878787878787878787878787878787878",
        Expect::Parse("incomplete punicode string"),
    );
    check_rep(
        "idna",
        "786e2d2d78787878787878787878787878787878787878787878787878787878",
        Expect::Server,
    );
    check_one("idna", "786e2d2d412d7a6d63", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d412d7a6d63",
        Expect::Parse("Violation of BIDI requirement 2"),
    );
    check_rep("idna", "786e2d2d412d7a6d63", Expect::Server);
    check_one("idna", "786e2d2d61", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d61",
        Expect::Parse("Invalid character '\\x80'"),
    );
    check_rep("idna", "786e2d2d61", Expect::Server);
    check_one("idna", "786e2d2d66612d686961", Expect::Server);
    check_stream(
        "idna",
        "786e2d2d66612d686961",
        Expect::Parse("('IDNA does not round-trip', b'xn--fa-hia', b'fass')"),
    );
    check_rep("idna", "786e2d2d66612d686961", Expect::Server);
    check_one(
        "idna",
        "786e2d2d6361662d646d61",
        Expect::Ok("caf\u{e9}", &[]),
    );
    check_stream(
        "idna",
        "786e2d2d6361662d646d61",
        Expect::Ok("caf\u{e9}", &[]),
    );
    check_rep("idna", "786e2d2d6361662d646d61", Expect::Server);
    check_one("idna", "61622d2d786e2d2d61", Expect::Ok("ab--xn--a", &[]));
    check_stream("idna", "61622d2d786e2d2d61", Expect::Ok("ab--xn--a", &[]));
    check_rep("idna", "61622d2d786e2d2d61", Expect::Server);
}

#[test]
fn battery_hz_c() {
    check_one("hz", "7e7b21", Expect::Fallback);
    check_stream(
        "hz",
        "7e7b21",
        Expect::Parse(
            "'hz' codec can't decode byte 0x21 in position 2: incomplete multibyte sequence",
        ),
    );
    check_rep("hz", "7e7b21", Expect::Ok("\u{fffd}", &[]));
    check_one("hz", "7e7b20217e7d", Expect::Fallback);
    check_stream(
        "hz",
        "7e7b20217e7d",
        Expect::Parse(
            "'hz' codec can't decode byte 0x20 in position 2: illegal multibyte sequence",
        ),
    );
    check_rep(
        "hz",
        "7e7b20217e7d",
        Expect::Ok("\u{fffd}\u{3013}\u{fffd}", &[]),
    );
    check_one("hz", "7e7b2121", Expect::Ok("\u{3000}", &[]));
    check_stream("hz", "7e7b2121", Expect::Ok("\u{3000}", &[]));
    check_rep("hz", "7e7b2121", Expect::Ok("\u{3000}", &[]));
    check_one("hz", "417e", Expect::Fallback);
    check_stream(
        "hz",
        "417e",
        Expect::Parse(
            "'hz' codec can't decode byte 0x7e in position 1: incomplete multibyte sequence",
        ),
    );
    check_rep("hz", "417e", Expect::Ok("A\u{fffd}", &[]));
    check_one("hz", "7e7b7f7f7e7d", Expect::Fallback);
    check_stream(
        "hz",
        "7e7b7f7f7e7d",
        Expect::Parse(
            "'hz' codec can't decode byte 0x7f in position 2: illegal multibyte sequence",
        ),
    );
    check_rep("hz", "7e7b7f7f7e7d", Expect::Ok("\u{fffd}\u{fffd}", &[]));
    check_one("hz", "7e7b217f7e7d", Expect::Fallback);
    check_stream(
        "hz",
        "7e7b217f7e7d",
        Expect::Parse(
            "'hz' codec can't decode byte 0x21 in position 2: illegal multibyte sequence",
        ),
    );
    check_rep("hz", "7e7b217f7e7d", Expect::Ok("\u{fffd}\u{fffd}", &[]));
    check_one("hz", "7e7e7b", Expect::Ok("~{", &[]));
    check_stream("hz", "7e7e7b", Expect::Ok("~{", &[]));
    check_rep("hz", "7e7e7b", Expect::Ok("~{", &[]));
    check_one("hz", "7e7b7e7d", Expect::Ok("", &[]));
    check_stream("hz", "7e7b7e7d", Expect::Ok("", &[]));
    check_rep("hz", "7e7b7e7d", Expect::Ok("", &[]));
}

