    check_stream("euc_jp", "8fa2b1", Expect::Ok("\u{b8}", &[]));
    check_one("euc_jp", "8fa2b2", Expect::Ok("\u{2d9}", &[]));
    check_stream("euc_jp", "8fa2b2", Expect::Ok("\u{2d9}", &[]));
