    check_stream("euc_jp", "8fcdca", Expect::Ok("\u{759c}", &[]));
    check_one("euc_jp", "8fcdcb", Expect::Ok("\u{75a2}", &[]));
    check_stream("euc_jp", "8fcdcb", Expect::Ok("\u{75a2}", &[]));
    check_one("euc_jp", "8fede0", Expect::Ok("\u{9fa1}", &[]));
    check_stream("euc_jp", "8fede0", Expect::Ok("\u{9fa1}", &[]));
