#[test]
fn battery_utf_oneshot() {
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("e4b8"), "utf-8"),
        Err("'utf-8' codec can't decode bytes in position 0-1: unexpected end of data".to_string())
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("ff"), "utf-8"),
        Err("'utf-8' codec can't decode byte 0xff in position 0: invalid start byte".to_string())
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("4142ff"), "utf-8"),
        Err("'utf-8' codec can't decode byte 0xff in position 2: invalid start byte".to_string())
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("fffe41"), "utf-16"),
        Err("'utf-16-le' codec can't decode byte 0x41 in position 2: truncated data".to_string())
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("4142"), "utf-16"),
        Ok("\u{4241}".to_string())
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("feff00"), "utf-16"),
        Err("'utf-16-be' codec can't decode byte 0x00 in position 2: truncated data".to_string())
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("414243"), "utf-16-le"),
        Err("'utf-16-le' codec can't decode byte 0x43 in position 2: truncated data".to_string())
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("00d841"), "utf-16-le"),
        Err(
            "'utf-16-le' codec can't decode bytes in position 0-2: unexpected end of data"
                .to_string()
        )
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("00d800d8"), "utf-16-le"),
        Err(
            "'utf-16-le' codec can't decode bytes in position 0-1: illegal UTF-16 surrogate"
                .to_string()
        )
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("fffe00004142"), "utf-32"),
        Err("'utf-32-le' codec can't decode bytes in position 4-5: truncated data".to_string())
    );
    assert_eq!(dec::decode_utf_oneshot(&bytes_of("41424344"), "utf-32"), Err("'utf-32-le' codec can't decode bytes in position 0-3: code point not in range(0x110000)".to_string()));
    assert_eq!(dec::decode_utf_oneshot(&bytes_of("4142434445"), "utf-32-le"), Err("'utf-32-le' codec can't decode bytes in position 0-3: code point not in range(0x110000)".to_string()));
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("efbb"), "utf-8-sig"),
        Err("'utf-8' codec can't decode bytes in position 0-1: unexpected end of data".to_string())
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("efbbbfff"), "utf-8-sig"),
        Err("'utf-8' codec can't decode byte 0xff in position 0: invalid start byte".to_string())
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("efbbbf"), "utf-8-sig"),
        Ok("".to_string())
    );
    assert_eq!(
        dec::decode_utf_oneshot(&bytes_of("ff"), "utf-8-sig"),
        Err("'utf-8' codec can't decode byte 0xff in position 0: invalid start byte".to_string())
    );
}

#[test]
fn battery_u8sig() {
    check_one("utf-8-sig", "efbbbfff", Expect::Fallback);
    check_stream(
        "utf-8-sig",
        "efbbbfff",
        Expect::Parse("'utf-8' codec can't decode byte 0xff in position 0: invalid start byte"),
    );
    check_rep("utf-8-sig", "efbbbfff", Expect::Ok("\u{fffd}", &[]));
    check_one("utf-8-sig", "efbbbf41ff", Expect::Fallback);
    check_stream(
        "utf-8-sig",
        "efbbbf41ff",
        Expect::Parse("'utf-8' codec can't decode byte 0xff in position 1: invalid start byte"),
    );
    check_rep("utf-8-sig", "efbbbf41ff", Expect::Ok("A\u{fffd}", &[]));
    check_one("utf-8-sig", "efbbbfe4", Expect::Fallback);
    check_stream("utf-8-sig", "efbbbfe4", Expect::Ok("", &[]));
    check_rep("utf-8-sig", "efbbbfe4", Expect::Ok("\u{fffd}", &[]));
    check_one("utf-8-sig", "efbbbfeda080", Expect::Fallback);
    check_stream(
        "utf-8-sig",
        "efbbbfeda080",
        Expect::Parse(
            "'utf-8' codec can't decode byte 0xed in position 0: invalid continuation byte",
        ),
    );
    check_rep(
        "utf-8-sig",
        "efbbbfeda080",
        Expect::Ok("\u{fffd}\u{fffd}\u{fffd}", &[]),
    );
}
